import{_ as t,o as i,c as n,a2 as a}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Linking Grids","description":"Link entries between Grids and spread data sensibly across multiple tables.","frontmatter":{"title":"Linking Grids","description":"Link entries between Grids and spread data sensibly across multiple tables."},"headers":[],"relativePath":"en/grids/verknuepfungen.md","filePath":"en/grids/verknuepfungen.md","lastUpdated":1787319236000}'),s={name:"en/grids/verknuepfungen.md"};function r(o,e,l,d,c,p){return i(),n("div",null,[...e[0]||(e[0]=[a(`<h1 id="linking-grids" tabindex="-1">Linking Grids <a class="header-anchor" href="#linking-grids" aria-label="Permalink to &quot;Linking Grids&quot;">​</a></h1><p>A <strong>link</strong> connects an entry to one or more entries in another Grid. This lets you spread data sensibly instead of cramming everything into one wide table.</p><h2 id="when-it-pays-off" tabindex="-1">When it pays off <a class="header-anchor" href="#when-it-pays-off" aria-label="Permalink to &quot;When it pays off&quot;">​</a></h2><p>When values repeat, they belong in their own Grid.</p><p>An example: you record registrations for events. Without a link, every registration repeats the event name, the date, and the location. If the location changes, you&#39;d have to update it everywhere.</p><p>With a link:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Grid &quot;Events&quot;                  Grid &quot;Registrations&quot;</span></span>
<span class="line"><span>├── Title                      ├── Name</span></span>
<span class="line"><span>├── Date           ←───────────┤ Event         (Link record)</span></span>
<span class="line"><span>├── Location                   ├── Email</span></span>
<span class="line"><span>└── Price                      └── Status</span></span></code></pre></div><p>The location is stored <strong>once</strong>. Every registration points to it.</p><div class="tip custom-block"><p class="custom-block-title">The rule of thumb</p><p>If a value appears identically in multiple rows, it belongs in its own Grid. This applies to customers, products, locations, projects, categories.</p></div><h2 id="the-two-link-types" tabindex="-1">The two link types <a class="header-anchor" href="#the-two-link-types" aria-label="Permalink to &quot;The two link types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column type</th><th>Refers to</th></tr></thead><tbody><tr><td><strong>Link record</strong></td><td>exactly one entry</td></tr><tr><td><strong>Link multiple records</strong></td><td>any number of entries</td></tr></tbody></table><p><strong>Link record</strong> is the standard case: a registration belongs to one event, an invoice to one customer.</p><p><strong>Link multiple records</strong> is used when several things belong together: a project has multiple participants, an invoice has multiple line items.</p><h2 id="create-a-link" tabindex="-1">Create a link <a class="header-anchor" href="#create-a-link" aria-label="Permalink to &quot;Create a link&quot;">​</a></h2><ol><li>Create a new field in the Grid.</li><li>Choose <strong>Link record</strong> or <strong>Link multiple records</strong>.</li><li>Under <em>Specify the Grid view</em> choose the target view.</li></ol><div class="warning custom-block"><p class="custom-block-title">You choose a view, not a Grid</p><p>The selection happens via a <strong>view</strong> of the target Grid. That has a practical consequence: if the view is filtered, only the filtered entries are available to choose from.</p><p>You can use this deliberately — a view &quot;Active customers&quot; prevents someone from picking an inactive customer. But it can also be surprising when an expected entry doesn&#39;t show up. In that case, check the target view&#39;s filter.</p></div><h2 id="using-a-link" tabindex="-1">Using a link <a class="header-anchor" href="#using-a-link" aria-label="Permalink to &quot;Using a link&quot;">​</a></h2><p>In the table, clicking the field opens the picker. You search for the entry you want and select it. If nothing matches, ApptiveGrid reports <em>No matching entry found.</em></p><p>In <a href="/en/formulare/felder-konfigurieren">forms</a>, the same picker appears for people filling in the form.</p><h2 id="the-limit-no-nested-links" tabindex="-1">The limit: no nested links <a class="header-anchor" href="#the-limit-no-nested-links" aria-label="Permalink to &quot;The limit: no nested links&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Links can&#39;t be chained arbitrarily</p><p>If you try to reference a Grid that is itself already linked elsewhere, ApptiveGrid reports:</p><blockquote><p><em>Links to Grids that are already linked elsewhere are not yet possible.</em></p></blockquote><p>So a chain like <code>Registration → Event → Venue</code> isn&#39;t possible.</p></div><p><strong>What you can do instead:</strong></p><ul><li><strong>Keep the data model flat.</strong> Store location and date directly in &quot;Events&quot; instead of building another reference.</li><li><strong>Link directly.</strong> Have &quot;Registrations&quot; additionally reference &quot;Venues&quot; directly.</li><li><strong>Use linked value.</strong> Pull the value you need over via a <a href="/en/grids/berechnete-felder">calculated field</a> instead of creating another link.</li></ul><p>Plan your data model with this limit in mind from the start. Restructuring afterward is a lot of work.</p><h2 id="deleting-entries-with-links" tabindex="-1">Deleting entries with links <a class="header-anchor" href="#deleting-entries-with-links" aria-label="Permalink to &quot;Deleting entries with links&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Linked entries can&#39;t be deleted without further ado</p><p>If an entry is referenced elsewhere, ApptiveGrid reports:</p><blockquote><p><em>Delete not possible. The entry is still referenced elsewhere.</em></p></blockquote><p>Or, if the referencing entry can be named:</p><blockquote><p><em>Delete not possible. The entry is still referenced by {entry}.</em></p></blockquote><p>Remove the links pointing to this entry first. This is a safeguard — it prevents references from pointing into thin air.</p></div><p>With many references, a filtered view in the referencing Grid helps you find all affected entries.</p><h2 id="filtering-by-links" tabindex="-1">Filtering by links <a class="header-anchor" href="#filtering-by-links" aria-label="Permalink to &quot;Filtering by links&quot;">​</a></h2><p>Link fields support the conditions <em>is empty</em> and <em>is not empty</em>. For <strong>Link multiple records</strong>, <em>contains any of</em>, <em>contains none of</em>, and <em>contains all of</em> are also available.</p><div class="tip custom-block"><p class="custom-block-title">Finding incomplete records</p><p>A filter <code>Event</code> <code>is empty</code> shows all registrations without an assigned event — the fastest way to spot data gaps after an import.</p></div><h2 id="what-becomes-possible-afterward" tabindex="-1">What becomes possible afterward <a class="header-anchor" href="#what-becomes-possible-afterward" aria-label="Permalink to &quot;What becomes possible afterward&quot;">​</a></h2><p>The calculated field types only work once a link exists:</p><ul><li><strong>Use linked value</strong> — pulls a value from the linked entry, e.g. the event date into the registration</li><li><strong>Calculate sum</strong> — sums across multiple linked entries, e.g. the line items of an invoice</li></ul><p>→ <a href="/en/grids/berechnete-felder">Calculated Fields</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/grids/berechnete-felder">Calculated Fields</a></li><li><a href="/en/referenz/spaltentypen">Column type reference</a></li><li><a href="/en/grids/felder">Creating and changing fields</a></li><li><a href="/en/grids/flow-button">Start a flow via a button from an entry</a></li></ul>`,36)])])}const f=t(s,[["render",r]]);export{u as __pageData,f as default};
